def _flatten_schema(raw: Dict[str, Any], prefix: str = "") -> Dict[str, Dict[str, Any]]:
    """Flatten the nested TOML schema into {dotpath: {type, default, ...}}.

    A table is a *section* iff it has at least one table child; otherwise it is
    a leaf table and therefore a parameter definition. Keying off the presence
    of a "type" key instead silently discards any definition that misspells or
    omits "type", so load_schema() can never report it as malformed.
    """
    result: Dict[str, Dict[str, Any]] = {}
    for key, value in raw.items():
        full_key = f"{prefix}.{key}" if prefix else key
        if not isinstance(value, dict):
            continue
        if any(isinstance(child, dict) for child in value.values()):
            # This is a section, recurse
            result.update(_flatten_schema(value, full_key))
        else:
            # This is a parameter definition; load_schema() validates it
            result[full_key] = value
    return result

